files.content:
.segmented-item:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
.segmented{
  position:relative;
  display:inline-flex;
  align-items:stretch;
  padding:var(--s-1);
  background:var(--surface-sunken);
  border:var(--bw-1) solid var(--border-subtle);
  border-radius:var(--r-full);
}
.segmented-fill{
  display:flex;
}
.segmented-item{
  position:relative;
  z-index:1;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--s-2);
  height:var(--s-10);
  padding:0 var(--s-4);
  background:transparent;
  border:none;
  border-radius:var(--r-full);
  cursor:pointer;
  font-family:var(--font-sans);
  font-size:var(--t-small);
  font-weight:500;
  line-height:1;
  white-space:nowrap;
  color:var(--obsidian-300);
  transition:color var(--d-quick) var(--ease-standard);
}
.segmented-fill .segmented-item{
  flex:1 1 0;
}
.segmented-item:hover{
  color:var(--obsidian-100);
}
.segmented-item:active{
  color:var(--obsidian-300);
}
.segmented-item[aria-selected="true"]{
  color:var(--obsidian-100);
}
.segmented-thumb{
  position:absolute;
  top:var(--s-1);
  bottom:var(--s-1);
  left:0;
  width:0;
  background:var(--obsidian-700);
  border:var(--bw-1) solid var(--border-input);
  border-radius:var(--r-full);
  box-shadow:var(--sh-1);
  transition:transform var(--d-base) var(--ease-decel), width var(--d-base) var(--ease-decel);
  pointer-events:none;
  will-change:transform,width;
}
.segmented-panel{
  opacity:0;
  transform:translateY(6px);
  transition:opacity var(--d-quick) var(--ease-standard), transform var(--d-quick) var(--ease-standard);
}
@media (prefers-reduced-motion: reduce){
  .segmented-item, .segmented-thumb{
    transition:none;
  }
  .segmented-panel{
    transition:none;
    opacity:1;
    transform:none;
  }
}
